-- Table: masterdata_config
-- Source: accounting_admin_db.sql (1. Master data)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS masterdata_config (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    config_key   VARCHAR(100) NOT NULL UNIQUE,
    config_value JSONB        NOT NULL DEFAULT 'null'::jsonb,
    config_group VARCHAR(50)  NOT NULL DEFAULT 'general',
    data_type    VARCHAR(20)  NOT NULL DEFAULT 'string'
                 CHECK (data_type IN ('string', 'number', 'boolean', 'json', 'date')),
    description  TEXT,
    is_public    BOOLEAN      NOT NULL DEFAULT FALSE,
    is_editable  BOOLEAN      NOT NULL DEFAULT TRUE,
    updated_by   BIGINT REFERENCES masterdata_user(id),
    created_at   TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at   TIMESTAMPTZ  NOT NULL DEFAULT now()
);
